WITH with_latest AS (SELECT s.*, top1.quantity, top1.unit_price FROM orders s LEFT JOIN LATERAL (SELECT c.quantity, c.unit_price FROM order_items c WHERE c.order_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, customer_id, order_date, channel, shipping_fee, quantity, CASE WHEN channel RLIKE '^(store|mobile)$' THEN 'PRIORITY' ELSE 'GROUP_B' END AS channel_zone FROM with_latest ORDER BY quantity DESC, customer_id
